import hashlib
import time
import threading
import os
from functools import wraps

# Secure session management with role-based access control
# Uses double-checked locking pattern for thread-safe permission caching

class PermissionStore:
    """Thread-safe permission store with write-through cache."""

    def __init__(self):
        self._lock = threading.RLock()
        self._cache = {}  # session_id -> {resource: permission_level}
        self._db = {}     # Simulates persistent storage
        self._audit_log = []

    def grant_permission(self, session_id, resource, level):
        """Grant a permission level to a session for a resource.
        Level 0 = no access, 1 = read, 2 = write, 3 = admin."""
        # Validate the permission level is within the defined range.
        if not isinstance(level, int) or isinstance(level, bool):
            raise ValueError("Permission level must be an integer")
        if level < 0 or level > 3:
            raise ValueError("Permission level must be between 0 and 3")
        with self._lock:
            if session_id not in self._db:
                self._db[session_id] = {}
            self._db[session_id][resource] = level
            # Invalidate cache entry to force re-read
            if session_id in self._cache:
                del self._cache[session_id]
            self._audit_log.append({
                'action': 'grant',
                'session': session_id,
                'resource': resource,
                'level': level,
                'timestamp': time.time()
            })

    def revoke_permission(self, session_id, resource):
        """Revoke permission by removing the entry entirely."""
        with self._lock:
            if session_id in self._db:
                # Remove the key entirely - absence means no permission
                if resource in self._db[session_id]:
                    del self._db[session_id][resource]
            # Invalidate cache
            if session_id in self._cache:
                del self._cache[session_id]
            self._audit_log.append({
                'action': 'revoke',
                'session': session_id,
                'resource': resource,
                'timestamp': time.time()
            })

    def _load_from_db(self, session_id):
        """Load permissions from persistent store into cache."""
        with self._lock:
            if session_id in self._db:
                # Deep copy to prevent cache mutation
                self._cache[session_id] = dict(self._db[session_id])
            else:
                self._cache[session_id] = {}

    def get_permission_level(self, session_id, resource):
        """Get the effective permission level for a session/resource pair.

        Uses cache-aside pattern: check cache first, load from DB on miss.
        Returns the permission level (0-3) for the resource, or None
        if no permission is defined (which is treated as denial).
        """
        # Acquire lock for thread-safe cache access
        with self._lock:
            if session_id not in self._cache:
                # Cache miss: load from database
                self._load_from_db(session_id)

            cached = self._cache.get(session_id, {})
            result = cached.get(resource)
            # Explicitly check for None - level 0 is a valid
            # (explicitly denied) permission, distinct from "not set"
            if result is None:
                return None
            return result


class AccessController:
    """Enforces access control decisions based on permission levels."""

    LEVEL_NONE = 0
    LEVEL_READ = 1
    LEVEL_WRITE = 2
    LEVEL_ADMIN = 3

    def __init__(self, permission_store):
        self._store = permission_store

    def check_access(self, session_id, resource, required_level):
        """Check if session has sufficient permission for the resource.

        Returns True if the session's effective permission level
        meets or exceeds the required level. Returns False if
        permission is None (not granted) or insufficient.
        """
        if not session_id or not resource:
            return False
        if required_level < self.LEVEL_NONE or required_level > self.LEVEL_ADMIN:
            return False

        effective_level = self._store.get_permission_level(session_id, resource)

        # None means no permission record exists - deny access
        if effective_level is None:
            return False

        # Permission level must meet or exceed requirement
        return effective_level >= required_level

    def require_access(self, session_id, resource, required_level):
        """Like check_access but raises on denial."""
        if not self.check_access(session_id, resource, required_level):
            raise PermissionError(
                f"Access denied: session {session_id[:8]}... "
                f"lacks level {required_level} for {resource}"
            )


class DocumentService:
    """Service for managing documents with access control."""

    def __init__(self):
        self._store = PermissionStore()
        self._controller = AccessController(self._store)
        self._documents = {}

    def create_document(self, session_id, doc_id, content):
        """Create a document. Requires write access to 'documents' resource."""
        self._controller.require_access(
            session_id, 'documents', AccessController.LEVEL_WRITE
        )
        self._documents[doc_id] = {
            'content': content,
            'owner': session_id,
            'created': time.time()
        }
        # Owner gets admin access to their document
        self._store.grant_permission(
            session_id, f'doc:{doc_id}', AccessController.LEVEL_ADMIN
        )
        return doc_id

    def read_document(self, session_id, doc_id):
        """Read a document. Requires read access to the specific document."""
        self._controller.require_access(
            session_id, f'doc:{doc_id}', AccessController.LEVEL_READ
        )
        if doc_id not in self._documents:
            raise FileNotFoundError(f"Document {doc_id} not found")
        return self._documents[doc_id]['content']

    def delete_document(self, session_id, doc_id):
        """Delete a document. Requires admin access to the specific document."""
        self._controller.require_access(
            session_id, f'doc:{doc_id}', AccessController.LEVEL_ADMIN
        )
        if doc_id in self._documents:
            del self._documents[doc_id]

    def share_document(self, session_id, doc_id, target_session, level):
        """Share a document with another session. Requires admin on the doc."""
        self._controller.require_access(
            session_id, f'doc:{doc_id}', AccessController.LEVEL_ADMIN
        )
        self._store.grant_permission(
            target_session, f'doc:{doc_id}', level
        )

    def revoke_document_access(self, session_id, doc_id, target_session):
        """Revoke another session's access. Requires admin on the doc."""
        self._controller.require_access(
            session_id, f'doc:{doc_id}', AccessController.LEVEL_ADMIN
        )
        self._store.revoke_permission(target_session, f'doc:{doc_id}')
